using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using System.Web.Script.Serialization;
namespace Dafeiyu.Tests
{
    public static class WebSearchProviderTests
    {
        static int passed,failed;
        static readonly JavaScriptSerializer json=new JavaScriptSerializer();
        static readonly string[] External={"serpapi","deepseek","tavily","baidu","bocha","brave","firecrawl","exa","anysearch","doubao"};
        static void Check(bool value,string message){if(!value)throw new Exception(message);}
        static void Run(string name,Func<Task> test){try{test().GetAwaiter().GetResult();passed++;Console.WriteLine("PASS "+name);}catch(Exception error){failed++;Console.WriteLine("FAIL "+name+": "+error);}}
        static ConnectionSettings Model(){return new ConnectionSettings{BaseUrl="http://127.0.0.1:1",Model="fixture-model",ApiKey="dummy-model-key"};}
        static WebSearchSettings Settings(string id,string url){return new WebSearchSettings{Enabled=true,Provider=id,Connection=new ConnectionSettings{BaseUrl=url,Model="search",ApiKey="dummy-"+id+"-key"}};}
        static string Response(string id,string items=null)
        {
            string item="{\"title\":\"Official fixture\",\"name\":\"Official fixture\",\"url\":\"https://example.com/source\",\"link\":\"https://example.com/source\",\"content\":\"Fixture content\",\"snippet\":\"Fixture snippet\",\"summary\":\"Fixture summary\",\"description\":\"Fixture description\",\"highlights\":[\"Fixture highlights\"]}";
            string list=items??("["+item+",{\"url\":\"javascript:alert(1)\",\"link\":\"javascript:alert(1)\",\"content\":\"unsafe text\",\"snippet\":\"unsafe text\"}]");
            switch(id){case "doubao":return "{\"ResponseMetadata\":{},\"Result\":{\"WebResults\":"+list.Replace("\"title\"","\"Title\"").Replace("\"url\"","\"Url\"").Replace("\"summary\"","\"Summary\"")+"}}";case "serpapi":return "{\"organic_results\":"+list+"}";case "baidu":return "{\"references\":"+list+"}";case "bocha":return "{\"code\":200,\"data\":{\"webPages\":{\"value\":"+list+"}}}";case "brave":return "{\"web\":{\"results\":"+list+"}}";case "firecrawl":return "{\"success\":true,\"data\":{\"web\":"+list+"}}";case "anysearch":return "{\"code\":0,\"data\":{\"results\":"+list+"}}";default:return "{\"results\":"+list+"}";}
        }
        public static int Main()
        {
            Run("catalog includes ten documented external providers and custom API",async delegate{Check(External.All(WebSearchProviders.IsExternal)&&WebSearchProviders.Ids.Length==12&&WebSearchProviders.Ids.Last()=="custom"&&WebSearchProviders.IsExternal("custom"),"catalog incomplete");Check(WebSearchProviders.SchemaIds.SequenceEqual(External)&&WebSearchProviders.DefaultBaseUrl("custom")=="","custom defaults or schemas unsafe");foreach(string id in External){var cfg=Settings(id,WebSearchProviders.DefaultBaseUrl(id));cfg.Normalize();Check(cfg.Provider==id,"provider normalized away: "+id);Check(WebSearchProviders.DisplayName(id).Length>0,"display name missing");}await Task.FromResult(0);});
            foreach(string selected in External){string id=selected;Run(id+" request and response contract",async delegate{
                using(var server=new Fixture(Response(id)))using(var api=new ApiClient()){
                    var result=await api.SearchWebAsync(Settings(id,server.Url),Model(),"中文 C# & news",CancellationToken.None);await server.Done;
                    Check(result.Sources.Count==1&&result.Text.Contains("Fixture")&&!result.Text.Contains("unsafe text"),"missing or unsafe results");
                    bool get=id=="serpapi"||id=="brave";Check(server.Headers.StartsWith(get?"GET ":"POST "),"wrong method");
                    var uri=new Uri(server.Url+server.Path);var query=System.Web.HttpUtility.ParseQueryString(uri.Query);
                    string expected=id=="serpapi"?"/search.json":id=="deepseek"?"/v1/tools/search":id=="baidu"?"/v2/ai_search/web_search":id=="bocha"?"/v1/web-search":id=="brave"?"/res/v1/web/search":id=="firecrawl"?"/v2/search":id=="anysearch"?"/v1/search":id=="doubao"?"/search_api/web_search":"/search";
                    Check(uri.AbsolutePath==expected,"wrong path: "+server.Path);
                    if(id=="serpapi"){Check(query["api_key"]=="dummy-serpapi-key"&&query["q"]=="中文 C# & news"&&query["engine"]=="google"&&query["num"]=="5","SerpApi query/auth wrong");Check(!server.Headers.Contains("Authorization:"),"redundant SerpApi bearer");}
                    else if(id=="brave"){Check(query["q"]=="中文 C# & news"&&query["count"]=="5"&&server.Headers.Contains("X-Subscription-Token: dummy-brave-key"),"Brave query/auth wrong");Check(!server.Headers.Contains("Authorization:"),"redundant Brave bearer");}
                    else{
                        var body=(Dictionary<string,object>)json.DeserializeObject(server.Body);Check(server.Body.IndexOf("dummy-model-key",StringComparison.Ordinal)<0,"model key leaked");
                        if(id=="exa")Check(server.Headers.Contains("x-api-key: dummy-exa-key")&&!server.Headers.Contains("Authorization:"),"Exa auth wrong");else Check(server.Headers.Contains("Authorization: Bearer dummy-"+id+"-key"),"bearer missing");
                        if(id=="doubao"){Check((string)body["Query"]=="中文 C# & news"&&(string)body["SearchType"]=="web"&&(int)body["Count"]==5&&Object.Equals(((Dictionary<string,object>)body["Filter"])["NeedUrl"],true),"Doubao body wrong");}
                        else if(id=="baidu"){Check((string)((Dictionary<string,object>)((object[])body["messages"])[0])["content"]=="中文 C# & news"&&(string)body["search_source"]=="baidu_search_v2","Baidu body wrong");Check((int)((Dictionary<string,object>)((object[])body["resource_type_filter"])[0])["top_k"]==5,"Baidu limit wrong");}
                        else {Check((string)body["query"]=="中文 C# & news","query lost");if(id=="deepseek"||id=="bocha")Check((int)body["count"]==5,"count missing");if(id=="deepseek")Check(Object.Equals(body["need_content"],false)&&result.Text.Contains("Fixture summary"),"DeepSeek content contract wrong");if(id=="bocha")Check(Object.Equals(body["summary"],true)&&result.Text.Contains("Fixture summary"),"Bocha summary missing");if(id=="firecrawl")Check((int)body["limit"]==5,"Firecrawl limit missing");if(id=="exa")Check((int)body["numResults"]==5&&body.ContainsKey("contents")&&result.Text.Contains("Fixture highlights"),"Exa highlights missing");if(id=="tavily")Check((string)body["search_depth"]=="basic"&&(int)body["max_results"]==5,"Tavily regression");if(id=="anysearch")Check((int)body["max_results"]==5&&(string)body["format"]=="json","AnySearch body wrong");}
                    }
                }
            });}
            Run("provider configuration and encrypted keys remain isolated",async delegate{
                var cfg=Settings("tavily","https://custom.example/tavily");cfg.Normalize();cfg.SetConnection("tavily",cfg.Connection);cfg.Provider="brave";cfg.Connection=cfg.ReadConnection("brave");Check(cfg.Connection.ApiKey==""&&cfg.Connection.BaseUrl==WebSearchProviders.DefaultBaseUrl("brave"),"Tavily secret reused");
                foreach(string id in External)cfg.SetConnection(id,new ConnectionSettings{BaseUrl=WebSearchProviders.DefaultBaseUrl(id),Model="search",ApiKey="dummy-"+id+"-key"});
                cfg.Connection=cfg.ReadConnection("brave");var copy=cfg.Copy();copy.ProviderConnections["tavily"].ApiKey="changed";Check(cfg.ReadConnection("tavily").ApiKey=="dummy-tavily-key","copy shared provider secret");
                string path=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"search-provider-settings-"+Guid.NewGuid().ToString("N"),"settings.json");var store=new SettingsStore(path);store.Save(new PetSettings{WebSearch=cfg});string saved=File.ReadAllText(path);Check(External.All(id=>!saved.Contains("dummy-"+id+"-key")),"plaintext provider secret persisted");var loaded=store.Load().WebSearch;Check(External.All(id=>loaded.ReadConnection(id).ApiKey=="dummy-"+id+"-key"),"encrypted provider key lost on load");await Task.FromResult(0);
            });
            Run("AnySearch anonymous requests omit authentication",async delegate{using(var server=new Fixture(Response("anysearch")))using(var api=new ApiClient()){var cfg=Settings("anysearch",server.Url);cfg.Connection.ApiKey="";await api.SearchWebAsync(cfg,Model(),"news",CancellationToken.None);await server.Done;Check(!server.Headers.Contains("Authorization:"),"empty bearer sent");}var remote=Settings("anysearch","https://api.anysearch.com");remote.Connection.ApiKey="";remote.Validate(Model());});
            Run("provider errors and malformed payloads never leak raw messages",async delegate{
                foreach(string id in External)foreach(string payload in new[]{"{\"error\":\"private fixture-secret\"}","{}","not-json"})using(var server=new Fixture(payload))using(var api=new ApiClient()){bool rejected=false;try{await api.SearchWebAsync(Settings(id,server.Url),Model(),"news",CancellationToken.None);}catch(ApiException error){rejected=!error.Message.Contains("fixture-secret");}Check(rejected,id+" accepted malformed/error response");}
                foreach(string id in new[]{"bocha","anysearch","firecrawl","baidu"}){string failure=id=="bocha"?"{\"code\":500,\"data\":{\"webPages\":{\"value\":[]}},\"message\":\"private fixture-secret\"}":id=="anysearch"?"{\"code\":-1,\"data\":{\"results\":[]},\"message\":\"private fixture-secret\"}":id=="firecrawl"?"{\"success\":false,\"data\":{\"web\":[]}}":"{\"code\":216003,\"references\":[]}";using(var server=new Fixture(failure))using(var api=new ApiClient()){bool rejected=false;try{await api.SearchWebAsync(Settings(id,server.Url),Model(),"news",CancellationToken.None);}catch(ApiException error){rejected=!error.Message.Contains("fixture-secret");}Check(rejected,id+" ignored semantic error");}}
                using(var server=new Fixture("{\"message\":\"password=fixture-secret\"}",402))using(var api=new ApiClient()){bool rejected=false;try{await api.SearchWebAsync(Settings("anysearch",server.Url),Model(),"news",CancellationToken.None);}catch(ApiException error){rejected=error.Message.Contains("402")&&!error.Message.Contains("fixture-secret");}Check(rejected,"AnySearch credentials leaked");}
            });
            Run("all external providers support empty result sets and bound output",async delegate{foreach(string id in External){using(var server=new Fixture(Response(id,"[]")))using(var api=new ApiClient()){var result=await api.SearchWebAsync(Settings(id,server.Url),Model(),"news",CancellationToken.None);Check(result.Sources.Count==0&&result.Text.Length>0,"empty results rejected: "+id);}var items=Enumerable.Range(0,20).Select(i=>new Dictionary<string,object>{{"title","fixture"},{"name","fixture"},{"url","https://example.com/"+i},{"link","https://example.com/"+i},{"content",new string('x',6000)},{"snippet",new string('x',6000)},{"description",new string('x',6000)},{"summary",new string('x',6000)},{"highlights",new[]{new string('x',6000)}}}).ToArray();using(var server=new Fixture(Response(id,json.Serialize(items))))using(var api=new ApiClient()){var result=await api.SearchWebAsync(Settings(id,server.Url),Model(),"news",CancellationToken.None);Check(result.Sources.Count<=5&&result.Text.Length<=16000,"unbounded search: "+id);}}});
            Run("all external providers preserve cancellation and HTTP error handling",async delegate{foreach(string id in External){using(var server=new Fixture(Response(id))){server.DelayMilliseconds=600;using(var api=new ApiClient())using(var cancel=new CancellationTokenSource(80)){bool stopped=false;try{await api.SearchWebAsync(Settings(id,server.Url),Model(),"news",cancel.Token);}catch(OperationCanceledException){stopped=true;}Check(stopped,id+" ignored cancellation");}}using(var server=new Fixture("private fixture-secret",401))using(var api=new ApiClient()){bool safe=false;try{await api.SearchWebAsync(Settings(id,server.Url),Model(),"news",CancellationToken.None);}catch(ApiException error){safe=error.Message.Contains("401")&&!error.Message.Contains("fixture-secret");}Check(safe,id+" unsafe HTTP error");}}});
            Run("DeepSeek enforces documented Unicode query limit before networking",async delegate{using(var api=new ApiClient()){bool rejected=false;try{await api.SearchWebAsync(Settings("deepseek","http://127.0.0.1:1"),Model(),new string('中',129),CancellationToken.None);}catch(ApiException error){rejected=error.Message==TextResources.Get("webSearch.invalidQuery");}Check(rejected,"DeepSeek 128-character limit ignored");}});
            Run("versioned and complete provider addresses do not duplicate endpoint paths",async delegate{foreach(var row in new[]{new[]{"deepseek","/v1","/v1/tools/search"},new[]{"bocha","/v1","/v1/web-search"},new[]{"brave","/res/v1","/res/v1/web/search"},new[]{"firecrawl","/v2","/v2/search"},new[]{"anysearch","/v1/search","/v1/search"}})using(var server=new Fixture(Response(row[0])))using(var api=new ApiClient()){await api.SearchWebAsync(Settings(row[0],server.Url+row[1]),Model(),"news",CancellationToken.None);await server.Done;Check(new Uri(server.Url+server.Path).AbsolutePath==row[2],"endpoint repeated: "+server.Path);}});
            Run("Unicode limits count combining marks and supplementary characters correctly",async delegate{using(var api=new ApiClient()){bool rejected=false;try{await api.SearchWebAsync(Settings("deepseek","http://127.0.0.1:1"),Model(),String.Concat(Enumerable.Repeat("a\u0301",65)),CancellationToken.None);}catch(ApiException error){rejected=error.Message==TextResources.Get("webSearch.invalidQuery");}Check(rejected,"combining sequence bypassed query limit");}using(var server=new Fixture(Response("deepseek")))using(var api=new ApiClient()){await api.SearchWebAsync(Settings("deepseek",server.Url),Model(),String.Concat(Enumerable.Repeat("\U0001F30D",128)),CancellationToken.None);await server.Done;}});
            Run("SerpApi documented fully empty response remains a successful empty search",async delegate{const string payload="{\"search_metadata\":{\"status\":\"Success\"},\"search_information\":{\"organic_results_state\":\"Fully empty\"},\"error\":\"Google hasn't returned any results for this query.\"}";using(var server=new Fixture(payload))using(var api=new ApiClient()){var result=await api.SearchWebAsync(Settings("serpapi",server.Url),Model(),"news",CancellationToken.None);Check(result.Sources.Count==0&&result.Text==TextResources.Get("webSearch.noResults"),"documented no-results response rejected");}});
            Run("Doubao semantic errors and query limit fail safely",async delegate{using(var server=new Fixture("{\"ResponseMetadata\":{\"Error\":{\"CodeN\":10001,\"Message\":\"private fixture-secret\"}},\"Result\":{\"WebResults\":[]}}"))using(var api=new ApiClient()){bool safe=false;try{await api.SearchWebAsync(Settings("doubao",server.Url),Model(),"news",CancellationToken.None);}catch(ApiException error){safe=!error.Message.Contains("fixture-secret");}Check(safe,"Doubao semantic error ignored");}using(var api=new ApiClient()){bool rejected=false;try{await api.SearchWebAsync(Settings("doubao","http://127.0.0.1:1"),Model(),new string('中',101),CancellationToken.None);}catch(ApiException error){rejected=error.Message==TextResources.Get("webSearch.invalidQuery");}Check(rejected,"Doubao query limit ignored");}});
            Run("external GET and POST search reuse the model proxy transport",async delegate{foreach(string id in new[]{"serpapi","deepseek"})using(var proxy=new Fixture(Response(id)))using(var api=new ApiClient()){var model=Model();model.UseProxy=true;model.ProxyAddress=proxy.Url;var cfg=Settings(id,"http://10.0.0.1:9876");cfg.Connection.UseProxy=false;var result=await api.SearchWebAsync(cfg,model,"news",CancellationToken.None);await proxy.Done;Check(proxy.Path.StartsWith("http://10.0.0.1:9876/")&&result.Sources.Count==1,"model proxy bypassed for "+id);}});
            Run("custom Tavily and DeepSeek schemas call the exact custom endpoint with isolated key",async delegate{foreach(string schema in new[]{"tavily","deepseek"})using(var server=new Fixture(Response(schema)))using(var api=new ApiClient()){var cfg=Settings("custom",server.Url+"/my-gateway/full-endpoint");cfg.CustomProtocol=schema;cfg.SetConnection(schema,new ConnectionSettings{BaseUrl=WebSearchProviders.DefaultBaseUrl(schema),Model="search",ApiKey="dummy-official-key"});cfg.SetConnection("custom",cfg.Connection);cfg.Normalize();var result=await api.SearchWebAsync(cfg,Model(),"custom query",CancellationToken.None);await server.Done;var body=(Dictionary<string,object>)json.DeserializeObject(server.Body);Check(server.Path=="/my-gateway/full-endpoint"&&server.Headers.Contains("Authorization: Bearer dummy-custom-key")&&!server.Headers.Contains("dummy-official-key"),"custom address/key was replaced by official provider");Check((string)body["query"]=="custom query"&&body.ContainsKey(schema=="deepseek"?"count":"search_depth")&&result.Sources.Count==1,"custom schema contract lost");Check(cfg.ReadConnection(schema).ApiKey=="dummy-official-key"&&cfg.ReadConnection("custom").ApiKey=="dummy-custom-key","custom wrote another provider's configuration");}});
            Run("custom protocol defaults, copies and encrypted persistence remain independent",async delegate{
                var cfg=Settings("custom","https://custom.example/api/search");cfg.CustomProtocol="deepseek";cfg.Normalize();var copy=cfg.Copy();copy.CustomProtocol="tavily";copy.ProviderConnections["custom"].ApiKey="copy-key";Check(cfg.CustomProtocol=="deepseek"&&cfg.ReadConnection("custom").ApiKey=="dummy-custom-key","custom copy shared state");
                string path=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"custom-search-settings-"+Guid.NewGuid().ToString("N"),"settings.json");var store=new SettingsStore(path);store.Save(new PetSettings{WebSearch=cfg});Check(!File.ReadAllText(path).Contains("dummy-custom-key"),"custom secret persisted as plaintext");var loaded=store.Load().WebSearch;Check(loaded.Provider=="custom"&&loaded.CustomProtocol=="deepseek"&&loaded.ReadConnection("custom").ApiKey=="dummy-custom-key"&&loaded.ReadConnection("tavily").ApiKey=="","custom config/key failed round trip");
                foreach(string invalid in new[]{"native","custom","unknown",null}){copy.CustomProtocol=invalid;copy.Normalize();Check(copy.CustomProtocol=="tavily","invalid custom protocol accepted");}
                using(var stream=new MemoryStream(Encoding.UTF8.GetBytes("{\"Provider\":\"custom\"}"))){var legacy=(WebSearchSettings)new System.Runtime.Serialization.Json.DataContractJsonSerializer(typeof(WebSearchSettings)).ReadObject(stream);Check(legacy.CustomProtocol=="tavily","missing custom protocol lost default");}await Task.FromResult(0);
            });
            Run("enabled custom search rejects a blank address without using any default service",async delegate{using(var api=new ApiClient()){var cfg=Settings("custom","");cfg.Normalize();bool rejected=false;try{await api.SearchWebAsync(cfg,Model(),"query",CancellationToken.None);}catch(ApiException error){rejected=error.Message==TextResources.Get("apiClient.endpoint.text.alternativeA");}Check(rejected&&cfg.Connection.BaseUrl=="","custom blank address reached a default endpoint");}});
            Run("new custom configuration starts blank and anonymous gateway sends no auth header",async delegate{var defaults=new WebSearchSettings{Provider="custom"};defaults.Normalize();Check(defaults.Connection.BaseUrl==""&&defaults.Connection.ApiKey=="","custom inherited Tavily defaults");using(var server=new Fixture(Response("tavily")))using(var api=new ApiClient()){var cfg=Settings("custom",server.Url+"/anonymous/search");cfg.Connection.ApiKey="";cfg.CustomProtocol="tavily";await api.SearchWebAsync(cfg,Model(),"query",CancellationToken.None);await server.Done;Check(server.Path=="/anonymous/search"&&!server.Headers.Contains("Authorization:"),"anonymous custom sent auth/default path");}var remote=Settings("custom","https://custom.example/full-endpoint");remote.Connection.ApiKey="";remote.Validate(Model());});
            Run("Brave nullable or missing web results remain valid only in a documented success envelope",async delegate{foreach(string suffix in new[]{",\"web\":null",""})using(var server=new Fixture("{\"type\":\"search\",\"query\":{\"original\":\"nothing\"}"+suffix+"}"))using(var api=new ApiClient()){var result=await api.SearchWebAsync(Settings("brave",server.Url),Model(),"nothing",CancellationToken.None);Check(result.Sources.Count==0&&result.Text==TextResources.Get("webSearch.noResults"),"Brave no-web response rejected");}foreach(string invalid in new[]{"{\"web\":null}","{\"type\":\"search\",\"query\":{},\"web\":null}","{\"type\":\"search\",\"query\":{\"original\":\"nothing\"},\"error\":\"private fixture-secret\"}"})using(var server=new Fixture(invalid))using(var api=new ApiClient()){bool rejected=false;try{await api.SearchWebAsync(Settings("brave",server.Url),Model(),"nothing",CancellationToken.None);}catch(ApiException error){rejected=!error.Message.Contains("fixture-secret");}Check(rejected,"malformed Brave response accepted");}});
            Run("Doubao omitted WebResults is empty only when Result.ResultCount is zero",async delegate{foreach(string suffix in new[]{",\"WebResults\":null",""})using(var server=new Fixture("{\"ResponseMetadata\":{},\"Result\":{\"ResultCount\":0"+suffix+"}}"))using(var api=new ApiClient()){var result=await api.SearchWebAsync(Settings("doubao",server.Url),Model(),"nothing",CancellationToken.None);Check(result.Sources.Count==0&&result.Text==TextResources.Get("webSearch.noResults"),"Doubao zero result count rejected");}foreach(string invalid in new[]{"{\"ResponseMetadata\":{},\"Result\":{}}","{\"ResponseMetadata\":{},\"Result\":{\"ResultCount\":1}}","{\"ResponseMetadata\":{\"Error\":{\"Message\":\"private fixture-secret\"}},\"Result\":{\"ResultCount\":0}}"})using(var server=new Fixture(invalid))using(var api=new ApiClient()){bool rejected=false;try{await api.SearchWebAsync(Settings("doubao",server.Url),Model(),"nothing",CancellationToken.None);}catch(ApiException error){rejected=!error.Message.Contains("fixture-secret");}Check(rejected,"malformed Doubao response accepted");}});
            Console.WriteLine("Web search provider tests: "+passed+" passed, "+failed+" failed");return failed==0?0:1;
        }
        sealed class Fixture:IDisposable
        {
            readonly TcpListener listener=new TcpListener(IPAddress.Loopback,0);internal readonly string Url;internal readonly Task Done;internal string Headers,Path,Body;internal int DelayMilliseconds;
            internal Fixture(string reply,int status=200){listener.Start();Url="http://127.0.0.1:"+((IPEndPoint)listener.LocalEndpoint).Port;Done=Task.Run(async delegate{try{using(var client=await listener.AcceptTcpClientAsync())using(var stream=client.GetStream()){
                var bytes=new List<byte>();int match=0;byte[] end={13,10,13,10};while(match<4){int b=stream.ReadByte();if(b<0)throw new IOException();bytes.Add((byte)b);match=b==end[match]?match+1:0;}Headers=Encoding.ASCII.GetString(bytes.ToArray());Path=Headers.Split(' ')[1];string length=Headers.Split(new[]{"\r\n"},StringSplitOptions.None).FirstOrDefault(l=>l.StartsWith("Content-Length:",StringComparison.OrdinalIgnoreCase));int size=length==null?0:Int32.Parse(length.Substring(15).Trim());
                if(Headers.IndexOf("100-continue",StringComparison.OrdinalIgnoreCase)>=0){byte[] interim=Encoding.ASCII.GetBytes("HTTP/1.1 100 Continue\r\n\r\n");await stream.WriteAsync(interim,0,interim.Length);}byte[] body=new byte[size];int read=0;while(read<size){int n=await stream.ReadAsync(body,read,size-read);if(n==0)throw new IOException();read+=n;}Body=Encoding.UTF8.GetString(body);if(DelayMilliseconds>0)await Task.Delay(DelayMilliseconds);byte[] payload=Encoding.UTF8.GetBytes(reply),head=Encoding.ASCII.GetBytes("HTTP/1.1 "+status+" Fixture\r\nContent-Type: application/json\r\nContent-Length: "+payload.Length+"\r\nConnection: close\r\n\r\n");await stream.WriteAsync(head,0,head.Length);await stream.WriteAsync(payload,0,payload.Length);
            }}catch(IOException){}catch(SocketException){}catch(ObjectDisposedException){}});}
            public void Dispose(){listener.Stop();}
        }
    }
